package com.smartcart.service;

import com.smartcart.dto.Models.*;
import com.smartcart.repository.Db;
import com.smartcart.exception.ApiException;
import com.smartcart.notification.NotificationService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static com.smartcart.repository.Db.*;

@Service
public class BudgetService {
    public static final ZoneId ZONE=ZoneId.of("Asia/Kolkata");
    private final Db db;private final CatalogService catalog;private final NotificationService notifications;
    public BudgetService(Db db,CatalogService catalog,NotificationService notifications){this.db=db;this.catalog=catalog;this.notifications=notifications;}
    public static String month(){return YearMonth.now(ZONE).toString();}
    private YearMonth parse(String month){try{return YearMonth.parse(month);}catch(Exception e){throw ApiException.bad("Use a month in YYYY-MM format.");}}
    public Budget budget(String user,String month){YearMonth m=parse(month);Instant start=m.atDay(1).atStartOfDay(ZONE).toInstant(),end=m.plusMonths(1).atDay(1).atStartOfDay(ZONE).toInstant();List<CategorySpend> categories=db.rows("SELECT c.name,SUM(t.amount_minor) AS total FROM budget_transactions t JOIN product_categories c ON c.id=t.category_id WHERE t.user_id=? AND t.occurred_at>=? AND t.occurred_at<? GROUP BY c.name ORDER BY total DESC",user,start,end).stream().map(r->new CategorySpend(text(r,"name"),num(r,"total"))).toList();long spent=categories.stream().mapToLong(CategorySpend::amountMinor).sum();Long limit=db.maybe("SELECT limit_minor FROM monthly_budgets WHERE user_id=? AND budget_month=?",user,month).map(r->num(r,"limit_minor")).orElse(null);return new Budget(month,limit,spent,limit==null?null:limit-spent,categories);}
    @Transactional public Budget save(String user,BudgetInput input){parse(input.month());var row=db.maybe("SELECT id FROM monthly_budgets WHERE user_id=? AND budget_month=?",user,input.month());if(row.isPresent())db.run("UPDATE monthly_budgets SET limit_minor=?,updated_at=? WHERE user_id=? AND budget_month=?",input.limitMinor(),Instant.now(),user,input.month());else db.insert("monthly_budgets",fields("id",id(),"user_id",user,"budget_month",input.month(),"limit_minor",input.limitMinor()));alert(user);return budget(user,input.month());}
    @Transactional public void expense(String user,ExpenseInput input){db.one("SELECT id FROM product_categories WHERE id=?",input.categoryId());db.insert("budget_transactions",fields("id",id(),"user_id",user,"category_id",input.categoryId(),"amount_minor",input.amountMinor(),"occurred_at",Instant.now(),"note",input.note().trim()));alert(user);}
    public List<MonthSpend> trend(String user){List<MonthSpend> result=new ArrayList<>();for(int i=5;i>=0;i--){String month=YearMonth.now(ZONE).minusMonths(i).toString();result.add(new MonthSpend(month,budget(user,month).spentMinor()));}return result;}
    public List<Purchase> history(String user){return db.rows("SELECT h.*,(SELECT SUM(quantity) FROM shopping_history_items i WHERE i.history_id=h.id) AS item_count FROM shopping_history h WHERE h.user_id=? ORDER BY h.purchased_at DESC LIMIT 100",user).stream().map(r->new Purchase(text(r,"id"),text(r,"platform_id"),num(r,"total_minor"),num(r,"savings_minor"),time(r,"purchased_at"),bool(r,"sample"),(int)num(r,"item_count"))).toList();}
    @Transactional public Purchase recordSample(String user,PurchaseInput input){if(!catalog.sample())throw ApiException.bad("Retailer-confirmed purchases are not connected. Record your actual receipt amount as an expense instead.");if(input.requestKey().length()>80)throw ApiException.bad("Invalid request key.");var existing=db.maybe("SELECT id FROM shopping_history WHERE user_id=? AND request_key=?",user,input.requestKey());if(existing.isPresent())return history(user).stream().filter(p->p.id().equals(text(existing.get(),"id"))).findFirst().orElseThrow();if(input.items().stream().map(BasketLine::productId).distinct().count()!=input.items().size())throw ApiException.bad("Duplicate items are not allowed.");db.one("SELECT id FROM grocery_platforms WHERE id=?",input.platform());String history=id();long total=0,savings=0;List<Map<String,Object>> records=new ArrayList<>();for(var i:input.items()){Product p=catalog.product(i.productId(),input.locationId());Offer o=p.offers().stream().filter(catalog::eligible).filter(v->v.platform().equals(input.platform())).findFirst().orElseThrow(()->ApiException.bad("A fresh available price is missing for one selected item."));long cost=o.priceMinor()*i.quantity();total+=cost;long max=p.offers().stream().filter(catalog::eligible).mapToLong(Offer::priceMinor).max().orElse(o.priceMinor());savings+=(max-o.priceMinor())*i.quantity();String category=text(db.one("SELECT p.category_id FROM products p JOIN product_variants v ON v.product_id=p.id WHERE v.id=?",p.id()),"category_id");records.add(fields("id",id(),"history_id",history,"variant_id",p.id(),"quantity",i.quantity(),"unit_price_minor",o.priceMinor(),"category_id",category));}
        db.insert("shopping_history",fields("id",history,"user_id",user,"location_id",input.locationId(),"platform_id",input.platform(),"total_minor",total,"savings_minor",savings,"purchased_at",Instant.now(),"sample",true,"request_key",input.requestKey()));for(var r:records){db.insert("shopping_history_items",r);db.insert("budget_transactions",fields("id",id(),"user_id",user,"history_id",history,"category_id",r.get("category_id"),"amount_minor",((Long)r.get("unit_price_minor"))*((Integer)r.get("quantity")),"occurred_at",Instant.now(),"note","Sample purchase recorded by user"));db.run("UPDATE replenishment_records SET last_purchased_at=?,updated_at=? WHERE user_id=? AND variant_id=?",Instant.now(),Instant.now(),user,r.get("variant_id"));}
        alert(user);return history(user).stream().filter(p->p.id().equals(history)).findFirst().orElseThrow();
    }
    private void alert(String user){Budget b=budget(user,month());if(b.limitMinor()!=null&&b.spentMinor()*10>=b.limitMinor()*9)notifications.emit(user,catalog.sample()?"Sample budget reminder":"Budget reminder","You have used at least 90% of your monthly grocery budget. Review optional purchases while keeping essentials in your plan.","BUDGET",user+":"+b.month()+":budget90",catalog.sample());}
    public List<Replenishment> replenishment(String user){return db.rows("SELECT r.*,p.name FROM replenishment_records r JOIN product_variants v ON v.id=r.variant_id JOIN products p ON p.id=v.product_id WHERE r.user_id=? AND r.enabled=TRUE ORDER BY r.last_purchased_at",user).stream().map(r->{Instant last=time(r,"last_purchased_at"),next=last.plus(Duration.ofDays(num(r,"cycle_days")));return new Replenishment(text(r,"id"),text(r,"variant_id"),text(r,"name"),(int)num(r,"cycle_days"),last,next,!next.isAfter(Instant.now()),"Estimate based on your configured consumption cycle. Check your pantry before buying.");}).toList();}
    public void cycle(String user,ReplenishmentInput input){db.one("SELECT id FROM product_variants WHERE id=?",input.productId());var row=db.maybe("SELECT id FROM replenishment_records WHERE user_id=? AND variant_id=?",user,input.productId());if(row.isPresent())db.run("UPDATE replenishment_records SET cycle_days=?,updated_at=? WHERE user_id=? AND variant_id=?",input.cycleDays(),Instant.now(),user,input.productId());else db.insert("replenishment_records",fields("id",id(),"user_id",user,"variant_id",input.productId(),"cycle_days",input.cycleDays(),"last_purchased_at",Instant.now()));}
    public void replenish(String user,String id){db.one("SELECT id FROM replenishment_records WHERE id=? AND user_id=?",id,user);db.run("UPDATE replenishment_records SET last_purchased_at=?,updated_at=? WHERE id=? AND user_id=?",Instant.now(),Instant.now(),id,user);}
    public void removeCycle(String user,String id){db.one("SELECT id FROM replenishment_records WHERE id=? AND user_id=?",id,user);db.run("DELETE FROM replenishment_records WHERE id=? AND user_id=?",id,user);}
    @org.springframework.scheduling.annotation.Scheduled(fixedDelay=300000) public void remind(){for(var user:db.rows("SELECT user_id FROM user_preferences WHERE replenishment_alerts=TRUE AND notifications_enabled=TRUE")){String id=text(user,"user_id");for(var r:replenishment(id))if(r.due())notifications.emit(id,(catalog.sample()?"Sample: ":"")+r.name()+" may need restocking",r.explanation(),"REPLENISHMENT",id+":"+r.id()+":"+r.lastPurchasedAt(),catalog.sample());}}
}
